/// The DX caret's blink timer, armed on the *view* window (whose message loop
/// has no other timers; WM_TIMER ids are per-window). The composed surface
/// sits above the GDI redirection surface, so the system caret is invisible
/// there and the blink has to be a draw state of our own.
pub(super) const DX_CARET_TIMER_ID: usize = 1;
/// One-shot nudge after a paint found the swapchain busy: it re-invalidates
/// the view so the newest state still lands once the compositor frees a buffer.
pub(super) const DX_RETRY_TIMER_ID: usize = 2;
pub(super) const DX_RETRY_MS: u32 = 8;
/// The 击键脉冲's one-shot timer: it exists only to hand the layer's opacity
/// back to the blink after the dip, and kills itself when it fires.
pub(super) const CARET_PULSE_TIMER_ID: usize = 3;
const CARET_PULSE_MS: u32 = 140;

/// `DOGEDIT_CARET_LAYER=off` puts the caret back inside the text frame — the
/// fallback path, and the drill the probes that read the swapchain back need
/// (they would otherwise stop seeing a caret at all, since the layer is
/// composited outside the back buffer).
fn caret_layer_enabled() -> bool {
    static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ON.get_or_init(|| {
        !std::env::var_os("DOGEDIT_CARET_LAYER").is_some_and(|v| v.eq_ignore_ascii_case("off"))
    })
}

/// `DOGEDIT_CARET_TRACE=1` — one line per caret state change on stderr. The
/// blink is either a compositor animation or a timer, and which one is running
/// is the first question every caret bug starts with.
fn caret_trace() -> bool {
    static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ON.get_or_init(|| std::env::var_os("DOGEDIT_CARET_TRACE").is_some())
}

/// Drill knob: `DOGEDIT_CARET_NOCLIP=1` drops the layer's text-area clip, to
/// tell "the clip is wrong" apart from "the layer is wrong" in one run.
fn caret_noclip() -> bool {
    static ON: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    *ON.get_or_init(|| std::env::var_os("DOGEDIT_CARET_NOCLIP").is_some())
}
