/// Smallest the dock can be dragged down to, and the editor floor that caps how
/// far it can be dragged up.
const SPLIT_MIN_DOCK: f32 = 40.0;
const SPLIT_MIN_EDITOR: f32 = 80.0;

/// The active caption after the one at `closed` is gone: panes after it shift
/// left, and closing the last caption leaves the new last one active.
fn next_active_after_close(active: usize, closed: usize, new_len: usize) -> usize {
    let active = if closed < active { active - 1 } else { active };
    active.min(new_len.saturating_sub(1))
}

/// The same pair for the left dock's splitter, which drags the panel's *width*:
/// the tree stays wide enough to read a file name, and the editor keeps a
/// column worth of text beside it.
const SPLIT_MIN_LEFT: f32 = 120.0;
const SPLIT_MIN_EDITOR_W: f32 = 240.0;

/// What a splitter band resizes. The band is always cut out of the host's own
/// inner edge (`DockPanel::split_rect`), so the editor window never owns a
/// pixel of it and cannot paint over it.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum SplitTarget {
    /// One host, by the side it is docked to. Every host is resized the same
    /// way: the bar is its inner edge, so a drag along that axis writes the
    /// host's size.
    Host(PanelSide),
}

/// Every band, in the order a press is tested. The bands are cut from
/// different hosts, so they are disjoint; the order only mirrors the
/// host slots.
const SPLIT_TARGETS: [SplitTarget; 4] = [
    SplitTarget::Host(PanelSide::Left),
    SplitTarget::Host(PanelSide::Right),
    SplitTarget::Host(PanelSide::Top),
    SplitTarget::Host(PanelSide::Bottom),
];

impl SplitTarget {
    /// A horizontal bar rides the pointer's y; a column bar its x.
    fn vertical(self) -> bool {
        let SplitTarget::Host(side) = self;
        matches!(side, PanelSide::Bottom | PanelSide::Top)
    }

    fn rules(self) -> BandRules {
        let SplitTarget::Host(side) = self;
        match side {
            PanelSide::Bottom => BandRules::FirstRow,
            PanelSide::Top => BandRules::LastRow,
            _ => BandRules::Columns,
        }
    }

    /// Whether a pointer delta grows the host (`+1`) or shrinks it (`-1`).
    /// A column host's bar is its right edge, a row host's is its top edge,
    /// except that a top host's bar is its bottom edge.
    fn sign(self) -> f32 {
        let SplitTarget::Host(side) = self;
        match side {
            PanelSide::Left | PanelSide::Top => 1.0,
            _ => -1.0,
        }
    }
}

/// A 160/255-alpha ghost of the band is the only thing that moves. The host takes its
/// new size once, on release. Nothing is resized while the pointer moves, so no child
/// window is moved under a stale paint and no old bar can be left behind.
struct SplitDrag {
    target: SplitTarget,
    /// Pointer position at the press, in the frame's client space.
    start: (i32, i32),
    /// The band's screen rect: what the ghost copies, body and thickness.
    band: (i32, i32, i32, i32),
    current: (i32, i32, i32, i32),
    /// `(size at press, floor, ceiling)` of the host the band resizes.
    size: (f32, f32, f32),
    /// Allowed delta along the drag axis; the ghost is clamped to it, so the
    /// release reads its size back without a second clamp.
    lo: i32,
    hi: i32,
    ghost: HWND,
    /// Whether the press that armed this drag saw a real button down. The
    /// watchdog only trusts `GetKeyState` once it has: a drag driven by posted
    /// messages (the repro harness) never moves the real button, and reading
    /// it there would end every drag 50 ms in.
    saw_button: bool,
}
