                // the low one in two messages, and each half alone is not a
                // `char`. Join the pair or every emoji typed through the
                // IME is silently dropped.
                let scalar = match ch {
                    0xD800..=0xDBFF => {
                        st.pending_high_surrogate = Some(ch as u16);
                        return Some(LRESULT(0));
                    }
                    0xDC00..=0xDFFF => {
                        let high = match st.pending_high_surrogate.take() {
                            Some(high) => high,
                            None => return Some(LRESULT(0)),
                        };
                        char::decode_utf16([high, ch as u16])
                            .next()
                            .and_then(|r| r.ok())
                    }
                    _ => {
                        st.pending_high_surrogate = None;
                        char::from_u32(ch)
                    }
                };
